        public void VerifyWiiu_Nkds(string idx, string system, string srcFormat, string srcInfo, string convert, string prmV, bool inScan, bool dats, bool datItem, string cfg, string outType, string resultString) => verifyTest(system, srcFormat, srcInfo, convert, prmV, inScan, dats, datItem, cfg, outType, resultString);
